def test_supervisor_once_can_fail_closed_on_reconciliation_result(
    monkeypatch,
    run_result,
    expected_exit_code,
):
    observed: dict[str, object] = {}

    class StubSupervisor:
        def __init__(self, config):
            observed["config"] = config

        def run_once(self, **_kwargs):
            observed["run_once_called"] = True
            return run_result

        def run_forever(self):
            raise AssertionError("--once must not start the supervisor loop")

    sentinel_config = object()
    monkeypatch.setattr(
        implementation_supervisor_module,
        "supervisor_config_from_args",
        lambda _args, *, repo_root: sentinel_config,
    )
    monkeypatch.setattr(
        implementation_supervisor_module,
        "PortalImplementationSupervisor",
        StubSupervisor,
    )

    exit_code = implementation_supervisor_module.main(
        [
            "--once",
            "--reconciliation-only",
            "--fail-on-reconciliation-error",
        ]
    )

    assert exit_code == expected_exit_code
    assert observed == {
        "config": sentinel_config,
        "run_once_called": True,
    }


def test_multi_supervisor_runner_parses_and_runs_short_track(tmp_path):
    worker = tmp_path / "worker.py"
    worker.write_text(
        "\n".join(
            [
                "import os",
                "import signal",
                "import sys",
                "import time",
                "from pathlib import Path",
                "signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))",
                "Path('state').mkdir(exist_ok=True)",
                "Path('state/observed.pid').write_text(str(os.getpid()), encoding='utf-8')",
                "Path('state/daemon.pid').write_text(str(os.getpid()), encoding='utf-8')",
                "print('worker started', flush=True)",
                "while True:",
                "    time.sleep(0.05)",
            ]
        )
        + "\n",
        encoding="utf-8",
    )
    track = parse_track_spec(
        "T|worker.py|logs/{stamp}.log|state/supervisor.pid|state/daemon.pid",
        stamp="RUN",
    )

    assert supervisor_track_payload(track)["log_path"] == "logs/RUN.log"

    output: list[str] = []
    result = run_supervisor_tracks(
        [track],
        repo_root=tmp_path,
        common_args=[],
        duration_seconds=0.15,
        heartbeat_interval_seconds=0.05,
        stop_grace_seconds=0.2,
        python_executable=sys.executable,
        master_pid_path=tmp_path / "state" / "master.pid",
        label="test runner",
        output=output.append,
    )

    pid = int((tmp_path / "state" / "observed.pid").read_text(encoding="utf-8").strip())
    assert result["completed"] is True
    assert result["track_count"] == 1
    assert result["all_trees_fenced"] is True
    assert result["master_pid_removed"] is True
    assert set(result["removed_runtime_markers"]) == {
        str(tmp_path / "state" / "supervisor.pid"),
        str(tmp_path / "state" / "daemon.pid"),
    }
    assert "worker started" in (tmp_path / "logs" / "RUN.log").read_text(encoding="utf-8")
    assert any("started T supervisor" in line for line in output)
    assert not pid_alive(pid)
    assert not (tmp_path / "state" / "master.pid").exists()
    assert not (tmp_path / "state" / "supervisor.pid").exists()
    assert not (tmp_path / "state" / "daemon.pid").exists()


def test_pid_alive_treats_an_unreaped_zombie_as_stopped():
    process = subprocess.Popen([sys.executable, "-c", "pass"])
    try:
        deadline = time.monotonic() + 5
        proc_stat = Path(f"/proc/{process.pid}/stat")
        while time.monotonic() < deadline:
            try:
                state = proc_stat.read_text(encoding="utf-8").rsplit(")", 1)[1].strip()[0]
            except (OSError, IndexError):
                state = ""
            if state == "Z":
                break
            time.sleep(0.01)
        assert state == "Z"
        assert not pid_alive(process.pid)
    finally:
        process.wait(timeout=5)


def test_multi_supervisor_runner_cleans_stale_daemon_pid_marker(tmp_path):
    worker = tmp_path / "worker.py"
    stale_pid = 999_999_999
    worker.write_text(
        "\n".join(
            [
                "import signal",
                "import sys",
                "import time",
                "from pathlib import Path",
                "signal.signal(signal.SIGTERM, lambda *_: sys.exit(0))",
                "Path('state').mkdir(exist_ok=True)",
                f"Path('state/daemon.pid').write_text('{stale_pid}\\n', encoding='utf-8')",
                "while True:",
                "    time.sleep(0.05)",
            ]
        )
        + "\n",
        encoding="utf-8",
    )
    track = parse_track_spec(
        "T|worker.py|logs/{stamp}.log|state/supervisor.pid|state/daemon.pid",
        stamp="RUN",
    )

    output: list[str] = []
    result = run_supervisor_tracks(
        [track],
        repo_root=tmp_path,
        common_args=[],
        duration_seconds=0.15,
        heartbeat_interval_seconds=0.05,
        stop_grace_seconds=0.2,
        python_executable=sys.executable,
        label="test runner",
        output=output.append,
    )

    heartbeat_lines = [line for line in output if "heartbeat T" in line]
    assert result["completed"] is True
    assert heartbeat_lines
    assert any("daemon_pid=unknown" in line for line in heartbeat_lines)
    assert any(f"stale_daemon_pid={stale_pid}" in line for line in heartbeat_lines)
    assert any("daemon_status=stale" in line for line in heartbeat_lines)
    assert any("removed_stale_daemon_pid_file=true" in line for line in heartbeat_lines)
