def test_implementation_daemon_retries_submodule_after_parent_commit_already_landed(
    tmp_path, monkeypatch
):
    # Ambient agent-lane LLM merge resolvers must not auto-heal dirty checkouts
    # in this deterministic dirty-gate regression (they hang and clear the race).
    monkeypatch.delenv(
        implementation_daemon_module.LLM_MERGE_RESOLVER_COMMAND_ENV,
        raising=False,
    )
    monkeypatch.delenv(
        implementation_daemon_module.LLM_MERGE_RESOLVER_TIMEOUT_ENV,
        raising=False,
    )
    repo, submodule = _seed_parent_with_submodule(tmp_path)
    (repo / "README.md").write_text("base\n", encoding="utf-8")
    _git(repo, "add", "README.md")
    _git(repo, "commit", "-m", "add parent readme")
    _git(repo, "checkout", "-b", "implementation/auto-116")
    (repo / "README.md").write_text("implementation\n", encoding="utf-8")
    _git(repo, "commit", "-am", "AUTO-116: parent change")
    implementation_commit = _git(repo, "rev-parse", "HEAD")
    _git(repo, "checkout", "main")

    submodule_branch = "implementation/auto-116-submodule-libs-child"
    _git(submodule, "checkout", "-b", submodule_branch)
    (submodule / "feature.txt").write_text("feature\n", encoding="utf-8")
    _git(submodule, "add", "feature.txt")
    _git(submodule, "commit", "-m", "AUTO-116: child change")
    submodule_commit = _git(submodule, "rev-parse", "HEAD")
    _git(submodule, "checkout", "main")
    ambient_main = _git(submodule, "rev-parse", "main")
    (submodule / "feature.txt").write_text("temporarily dirty\n", encoding="utf-8")

    state_dir = tmp_path / "supervisor-state"
    daemon = TodoImplementationDaemon(
        todo_path=repo / "missing.todo.md",
        state_path=state_dir / "task_state.json",
        strategy_path=state_dir / "strategy.json",
        events_path=state_dir / "events.jsonl",
        repo_root=repo,
        worktree_submodule_paths=["libs/child"],
        llm_merge_resolver_command="",
    )
    task = PortalTask(
        task_id="AUTO-116",
        title="Retry child after parent landed",
        status="todo",
        completion="manual",
        priority="P0",
        track="ops",
    )
    daemon._load_tasks = lambda: [task]  # type: ignore[method-assign]
    task_cid = daemon._identity_for_task(task).canonical_task_cid
    daemon._mark_reconciled_completion_in_todo = (  # type: ignore[method-assign]
        lambda *_args, **_kwargs: {
            "updated": False,
            "reason": "already_completed",
            "updated_task_ids": [],
            "already_completed_task_ids": [task.task_id],
            "completion_receipts": [
                {
                    "task_id": task.task_id,
                    "canonical_task_cid": task_cid,
                    "status": "succeeded",
                }
            ],
        }
    )
    first = daemon._merge_branch_to_main("implementation/auto-116", task, 1)

    assert first["merged"] is False
    assert first["reason"] == "submodule_merge_failed"
    assert first["submodule_merge_results"][0]["reason"] == "submodule_checkout_dirty"
    assert first["submodule_failure_rollback"]["reason"] == "parent_gitlinks_unchanged"
    assert _git(repo, "merge-base", "--is-ancestor", implementation_commit, "main") == ""
    checkpoint_path = state_dir / "merge_checkpoints" / "implementation-auto-116.json"
    assert checkpoint_path.exists()
    checkpoint = json.loads(checkpoint_path.read_text(encoding="utf-8"))
    assert "libs/child" in checkpoint["failed_submodules"]

    (submodule / "feature.txt").unlink()
    daemon._record_event(
        "implementation_finished",
        {
            "task_id": task.task_id,
            "task_cid": daemon._identity_for_task(
                task
            ).canonical_task_cid,
            "attempt": 1,
            "branch": "implementation/auto-116",
            "implementation_commit": implementation_commit,
            "merge_result": first,
        },
    )
    reconciliation = daemon._reconcile_failed_merges()

    assert reconciliation[-1]["resolved"] is True
    assert reconciliation[-1]["reason"] == "implementation_commit_already_merged"
    assert reconciliation[-1]["submodule_merge_results"][0]["merged"] is True
    assert _git(submodule, "rev-parse", "main") == ambient_main
    assert _git(submodule, "rev-parse", "HEAD") == submodule_commit
    assert _git(repo, "rev-parse", "main:libs/child") == submodule_commit
    assert not checkpoint_path.exists()


@pytest.mark.parametrize(
    "integration_record_location",
    ["top_level", "nested_train_callback"],
)
def test_implementation_daemon_reconciles_rewritten_branch_already_landed(
    tmp_path,
    integration_record_location,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    _git(repo, "config", "user.name", "Test User")
    _git(repo, "config", "user.email", "test@example.invalid")
    (repo / "base.txt").write_text("base\n", encoding="utf-8")
    _git(repo, "add", "base.txt")
    _git(repo, "commit", "-m", "base")

    branch = "implementation/auto-117"
    _git(repo, "checkout", "-b", branch)
    (repo / "feature.txt").write_text("feature\n", encoding="utf-8")
    _git(repo, "add", "feature.txt")
    _git(repo, "commit", "-m", "AUTO-117: feature")
    original_implementation_commit = _git(repo, "rev-parse", "HEAD")

    _git(repo, "checkout", "main")
    (repo / "concurrent.txt").write_text("concurrent\n", encoding="utf-8")
    _git(repo, "add", "concurrent.txt")
    _git(repo, "commit", "-m", "concurrent target change")
    _git(repo, "checkout", branch)
    _git(repo, "rebase", "main")
    rewritten_commit = _git(repo, "rev-parse", "HEAD")
    _git(repo, "checkout", "main")
    _git(repo, "merge", "--no-ff", "--no-edit", branch)
    rewritten_merge_commit = _git(repo, "rev-parse", "HEAD")

    todo_path = repo / "todo.md"
    todo_path.write_text(
        "## AUTO-117 Accept rewritten merge\n\n"
        "- Status: todo\n"
        "- Completion: manual\n",
        encoding="utf-8",
    )
    _git(repo, "add", "todo.md")
    _git(repo, "commit", "-m", "add task board")
    state_dir = tmp_path / "supervisor-state"
    daemon = TodoImplementationDaemon(
        todo_path=todo_path,
        state_path=state_dir / "task_state.json",
        strategy_path=state_dir / "strategy.json",
        events_path=state_dir / "events.jsonl",
        repo_root=repo,
        task_header_prefix="AUTO-",
    )
    task = daemon._load_tasks()[0]
    implementation_event = {
        "task_id": "AUTO-117",
        "task_cid": daemon._identity_for_task(
            task
        ).canonical_task_cid,
        "attempt": 1,
        "branch": branch,
        "implementation_commit": original_implementation_commit,
        "merge_result": {
            "attempted": True,
            "merged": False,
            "reason": "merge_retry_failed",
        },
    }
    if integration_record_location == "top_level":
        implementation_event["target_commit"] = rewritten_merge_commit
    else:
        implementation_event["merge_result"]["train_result"] = {
            "integrated": False,
            "merge_result": {
                "merged": False,
                "reason": "post_merge_integration_commit_unproven",
                "integration_occurred": True,
                "merge_commit": rewritten_merge_commit,
            },
        }
    daemon._record_event(
        "implementation_finished",
        implementation_event,
    )

    reconciliation = daemon._reconcile_failed_merges()

    assert reconciliation[-1]["resolved"] is True
    assert reconciliation[-1]["reason"] == "implementation_branch_already_merged"
    assert reconciliation[-1]["landed_ref_source"] == "branch"
    assert reconciliation[-1]["merge_commit"] == rewritten_merge_commit
    assert _git(repo, "merge-base", "--is-ancestor", rewritten_commit, "main") == ""
    assert not daemon._git_ref_is_ancestor(original_implementation_commit, "main")
    assert "- Status: completed" in todo_path.read_text(encoding="utf-8")
    assert daemon._successfully_merged_task_ids() == {"AUTO-117"}


def test_implementation_daemon_recovers_landed_merge_after_lock_deferral(
    tmp_path,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    _git(repo, "config", "user.name", "Test User")
    _git(repo, "config", "user.email", "test@example.invalid")
    (repo / "base.txt").write_text("base\n", encoding="utf-8")
    todo_path = repo / "todo.md"
    todo_path.write_text(
        "## AUTO-119 Recover a queued merge\n\n"
        "- Status: todo\n"
        "- Completion: manual\n"
        "- Outputs: feature.txt\n",
        encoding="utf-8",
    )
    _git(repo, "add", "base.txt", "todo.md")
    _git(repo, "commit", "-m", "baseline")

    branch = "implementation/auto-119"
    _git(repo, "checkout", "-b", branch)
    (repo / "feature.txt").write_text("feature\n", encoding="utf-8")
    _git(repo, "add", "feature.txt")
    _git(repo, "commit", "-m", "AUTO-119: feature")
    implementation_commit = _git(repo, "rev-parse", "HEAD")
    _git(repo, "checkout", "main")

    state_dir = tmp_path / "supervisor-state"
    daemon = TodoImplementationDaemon(
        todo_path=todo_path,
        state_path=state_dir / "task_state.json",
        strategy_path=state_dir / "strategy.json",
        events_path=state_dir / "events.jsonl",
        repo_root=repo,
        task_header_prefix="AUTO-",
        merge_target_branch="main",
    )
    task = daemon._load_tasks()[0]
    daemon._record_event(
        "implementation_finished",
        {
            "task_id": task.task_id,
            "task_cid": daemon._identity_for_task(
                task
            ).canonical_task_cid,
            "attempt": 1,
            "branch": branch,
            "implementation_commit": implementation_commit,
            "validation_result": {
                "attempted": True,
                "passed": True,
            },
            "merge_result": {
                "attempted": False,
                "merged": False,
                "reason": "lock_exists",
                "branch": branch,
            },
        },
    )

    # Simulate the queued merge landing after the lock-deferral event but
    # before the next reconciliation pass. The target is consequently stable
    # for the entire recovery invocation and there is no cached merge ref.
    _git(repo, "merge", "--no-ff", "--no-edit", branch)
    integration_commit = _git(repo, "rev-parse", "HEAD")

    reconciliation = daemon._reconcile_failed_merges()

    assert reconciliation[-1]["resolved"] is True
    assert reconciliation[-1]["reason"] == (
        "implementation_commit_already_merged"
    )
    assert reconciliation[-1]["landed_commit"] == implementation_commit
    assert reconciliation[-1]["merge_commit"] == integration_commit
    assert reconciliation[-1]["integration_commit_proof"]["passed"] is True
    assert reconciliation[-1][
        "post_merge_declared_output_invariant"
    ]["passed"] is True
    assert "- Status: completed" in todo_path.read_text(encoding="utf-8")
    assert daemon._successfully_merged_task_ids() == {"AUTO-119"}


