def test_supervisor_loop_accepts_fresh_child_log_when_semantic_heartbeat_is_stale(
    tmp_path,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    state_dir = repo / "state"
    state_dir.mkdir()
    status_path = state_dir / "daemon_status.json"
    status_path.write_text(
        json.dumps({"heartbeat_at": "2000-01-01T00:00:00+00:00"}),
        encoding="utf-8",
    )
    child_log_path = state_dir / "child.log"
    child_log_path.write_text("healthy idle pass\n", encoding="utf-8")
    spec = ManagedDaemonSpec(
        name="test-daemon",
        schema="test.daemon",
        repo_root=repo,
        daemon_dir=state_dir,
        runner=(sys.executable, "-c", "pass"),
        status_path=status_path,
        supervisor_status_path=state_dir / "supervisor_status.json",
        supervisor_pid_path=state_dir / "supervisor.pid",
        child_pid_path=state_dir / "child.pid",
        supervisor_out_path=state_dir / "supervisor.out",
        ensure_status_path=state_dir / "ensure_status.json",
        ensure_check_path=state_dir / "ensure_check.json",
    )
    child = SimpleNamespace(pid=os.getpid(), log_path=child_log_path)
    strict_loop = SupervisorLoop(
        SupervisorLoopConfig(
            spec=spec,
            command=(sys.executable, "-c", "pass"),
            log_prefix="child",
            watchdog_stale_after_seconds=60,
        )
    )
    strict = strict_loop.watchdog_decision(child)
    assert strict.reason == "stale_heartbeat"
    assert strict.detail["child_log_fallback_enabled"] is False

    loop = SupervisorLoop(
        SupervisorLoopConfig(
            spec=spec,
            command=(sys.executable, "-c", "pass"),
            log_prefix="child",
            watchdog_stale_after_seconds=60,
            watchdog_accept_fresh_child_log=True,
        )
    )

    assert loop.watchdog_decision(child).action == "continue"

    os.utime(child_log_path, (1, 1))

    stale = loop.watchdog_decision(child)
    assert stale.reason == "stale_heartbeat"
    assert stale.detail["child_log_fresh"] is False
    assert stale.detail["child_log_age_seconds"] > 60

    child_log_path.unlink()

    missing = loop.watchdog_decision(child)
    assert missing.reason == "stale_heartbeat"
    assert missing.detail["child_log_age_seconds"] is None


def test_supervisor_loop_starts_stall_clock_when_worker_disappears(tmp_path):
    repo = tmp_path / "repo"
    repo.mkdir()
    state_dir = repo / "state"
    spec = ManagedDaemonSpec(
        name="test-daemon",
        schema="test.daemon",
        repo_root=repo,
        daemon_dir=state_dir,
        runner=(sys.executable, "-c", "pass"),
        status_path=state_dir / "daemon_status.json",
        supervisor_status_path=state_dir / "supervisor_status.json",
        supervisor_pid_path=state_dir / "supervisor.pid",
        child_pid_path=state_dir / "child.pid",
        supervisor_out_path=state_dir / "supervisor.out",
        ensure_status_path=state_dir / "ensure_status.json",
        ensure_check_path=state_dir / "ensure_check.json",
    )
    clock = [100.0]
    loop = SupervisorLoop(
        SupervisorLoopConfig(
            spec=spec,
            command=(sys.executable, "-c", "pass"),
            log_prefix="child",
        ),
        monotonic=lambda: clock[0],
    )
    active = {
        "required": True,
        "phase": "implementing",
        "phase_age_seconds": 1800.0,
        "active_worker_count": 1,
        "active_worker_pids": [1234],
        "stalled_without_active_worker": False,
    }
    absent = {
        **active,
        "active_worker_count": 0,
        "active_worker_pids": [],
        "stalled_without_active_worker": True,
    }

    loop._worker_status_with_disappearance_grace(active, threshold_seconds=60)
    clock[0] = 110.0
    within_grace = loop._worker_status_with_disappearance_grace(
        absent,
        threshold_seconds=60,
    )
    clock[0] = 161.0
    expired = loop._worker_status_with_disappearance_grace(
        absent,
        threshold_seconds=60,
    )

    assert within_grace["worker_absence_age_seconds"] == 10.0
    assert within_grace["stalled_without_active_worker"] is False
    assert expired["worker_absence_age_seconds"] == 61.0
    assert expired["stalled_without_active_worker"] is True


def test_implementation_supervisor_recovers_after_child_loop_restart_exhaustion(tmp_path):
    repo = tmp_path / "repo"
    repo.mkdir()
    state_dir = repo / "state"
    state_dir.mkdir()

    class RecoveringLoop:
        calls = 0

        def __init__(self, config, *, watchdog_hook=None):
            self.config = config
            self.watchdog_hook = watchdog_hook

        def run(self):
            RecoveringLoop.calls += 1
            if RecoveringLoop.calls == 1:
                return SupervisorLoopResult(
                    status="max_restarts_reached",
                    restart_count=2,
                    last_exit_code=127,
                    last_recycle_reason="launch_failed",
                    last_run_id="first",
                    last_log_path="first.log",
                )
            return SupervisorLoopResult(status="stopped", restart_count=0, last_run_id="second")

    supervisor = TodoImplementationSupervisor(
        TodoSupervisorConfig(
            todo_path=repo / "todo.md",
            state_path=state_dir / "task_state.json",
            strategy_path=state_dir / "strategy.json",
            events_path=state_dir / "supervisor_events.jsonl",
            state_dir=state_dir,
            check_interval=0.01,
            max_restarts=1,
            repo_root=repo,
        )
    )
    supervisor.shared_supervisor_loop_class = RecoveringLoop
    supervisor.ensure_event_log_file = lambda: {"repaired": False, "reason": "valid"}
    supervisor.repair_main_checkout_merge_state = lambda: {"attempted": False, "repaired": False, "reason": "clean"}
    supervisor.ensure_managed_daemon_pid_file = lambda: {"adopted": False, "reason": "not_running"}
    run_once_calls: list[bool] = []

    def fake_run_once(*, include_refill=True):
        run_once_calls.append(include_refill)
        return {"stuck": False, "recovered": True}

    supervisor.run_once = fake_run_once
    supervisor._supervisor_loop_recovery_delay_seconds = lambda: 0.0

    supervisor.run_forever()

    assert RecoveringLoop.calls == 2
    assert run_once_calls == [False, True]
    events = [
        json.loads(line)
        for line in (state_dir / "supervisor_events.jsonl").read_text(encoding="utf-8").splitlines()
        if line.strip()
    ]
    assert [event["type"] for event in events] == [
        "supervisor_preflight_maintenance_pass",
        "supervisor_loop_finished",
        "supervisor_loop_recovery_pass",
        "supervisor_loop_restarting_after_recovery",
        "supervisor_loop_finished",
    ]
    assert events[1]["status"] == "max_restarts_reached"
    assert events[2]["recovery"]["recovered"] is True
    assert events[-1]["status"] == "stopped"


def test_implementation_supervisor_signal_cleans_managed_daemon_before_exit(
    tmp_path, monkeypatch
):
    from ipfs_accelerate_py.agent_supervisor.todo_daemon import (
        implementation_supervisor as supervisor_module,
    )

    repo = tmp_path / "repo"
    state_dir = repo / "state"
    state_dir.mkdir(parents=True)
    supervisor = TodoImplementationSupervisor(
        TodoSupervisorConfig(
            todo_path=repo / "todo.md",
            state_path=state_dir / "task_state.json",
            strategy_path=state_dir / "strategy.json",
            events_path=state_dir / "supervisor_events.jsonl",
            state_dir=state_dir,
            repo_root=repo,
        )
    )
    supervisor_status_path = state_dir / "portal_supervisor_status.json"
    supervisor_status_path.write_text(
        json.dumps(
            {
                "status": "running",
                "supervisor_pid": os.getpid(),
                "supervisor_pid_alive": True,
                "daemon_pid": 4321,
                "daemon_pid_alive": True,
                "active_worker_count": 1,
                "active_worker_pids": [9876],
                "worker_descendant_count": 1,
            }
        ),
        encoding="utf-8",
    )

    handlers = {
        signal.SIGTERM: "previous-term",
        signal.SIGINT: "previous-int",
    }
    transitions = []

    def fake_getsignal(signum):
        return handlers[signum]

    def fake_signal(signum, handler):
        previous = handlers[signum]
        handlers[signum] = handler
        transitions.append((signum, handler))
        return previous

    cleanup_calls = []
    recorded = []

    def fake_loop():
        handlers[signal.SIGTERM](signal.SIGTERM, None)

    monkeypatch.setattr(supervisor_module.signal, "getsignal", fake_getsignal)
    monkeypatch.setattr(supervisor_module.signal, "signal", fake_signal)
    monkeypatch.setattr(supervisor, "_run_forever_loop", fake_loop)
    monkeypatch.setattr(
        supervisor,
        "_terminate_managed_daemon_tree",
        lambda: cleanup_calls.append(True)
        or {
            "pid": 4321,
            "terminated": True,
            "quiesced": True,
            "remaining_pid": None,
        },
    )
    reconciliation_calls = []
    monkeypatch.setattr(
        supervisor,
        "_reconcile_interrupted_implementation_after_shutdown",
        lambda: reconciliation_calls.append(True)
        or {
            "reconciled": True,
            "blocked": False,
            "reason": "quiesced_active_attempt_reconciled",
        },
    )
    monkeypatch.setattr(
        supervisor,
        "_record_event",
        lambda event_type, payload: recorded.append((event_type, payload)),
    )

    with pytest.raises(SystemExit) as exc_info:
        supervisor.run_forever()

    assert exc_info.value.code == 128 + signal.SIGTERM
    assert cleanup_calls == [True]
    assert reconciliation_calls == [True]
    assert recorded == [
        (
            "supervisor_signal_shutdown",
            {
                "signal": signal.SIGTERM,
                "managed_daemon_cleanup": {
                    "pid": 4321,
                    "terminated": True,
                    "quiesced": True,
                    "remaining_pid": None,
                },
                "interrupted_implementation_reconciliation": {
                    "reconciled": True,
                    "blocked": False,
                    "reason": "quiesced_active_attempt_reconciled",
                },
            },
        )
    ]
    assert handlers == {
        signal.SIGTERM: "previous-term",
        signal.SIGINT: "previous-int",
    }
    assert len(transitions) == 4
    stopped = json.loads(supervisor_status_path.read_text(encoding="utf-8"))
    assert stopped["status"] == "stopped"
    assert stopped["supervisor_pid"] == os.getpid()
    assert stopped["supervisor_pid_alive"] is False
    assert stopped["daemon_pid"] is None
    assert stopped["daemon_pid_alive"] is False
    assert stopped["active_worker_count"] == 0
    assert stopped["active_worker_pids"] == []
    assert stopped["worker_descendant_count"] == 0
    assert stopped["stop_signal"] == signal.SIGTERM
    assert stopped["last_exit_code"] == 128 + signal.SIGTERM
    assert stopped["last_recycle_reason"] == "supervisor_signal_shutdown"
    assert stopped["managed_daemon_cleanup"]["terminated"] is True
    assert (
        stopped["interrupted_implementation_reconciliation"]["reconciled"]
        is True
    )


