def test_implementation_daemon_records_stage_specific_context_reserves(tmp_path):
    repo = tmp_path / "repo"
    repo.mkdir()
    todo_path = repo / "todo.md"
    todo_path.write_text("# Todos\n", encoding="utf-8")
    state_dir = repo / "state"
    state_dir.mkdir()
    daemon = TodoImplementationDaemon(
        todo_path=todo_path,
        state_path=state_dir / "task_state.json",
        strategy_path=state_dir / "strategy.json",
        events_path=state_dir / "events.jsonl",
        repo_root=repo,
        task_header_prefix="## ACCEL-",
        implementation_context_budget=ContextBudget(
            max_input_tokens=2_000,
            reserved_output_tokens=300,
            reserved_tool_tokens=100,
            max_items=64,
        ),
        implementation_context_tokenizer=lambda text: max(
            1, len(text.encode("utf-8")) // 16
        ),
        implementation_provider_context_window=2_400,
    )
    task = PortalTask(
        task_id="ACCEL-001",
        title="Compile implementation context",
        status="ready",
        completion="manual",
        priority="P0",
        track="runtime",
        outputs=["src/context.py"],
        validation=["pytest tests/test_context.py"],
        acceptance="Preserve implementation authority.",
        canonical_task_cid="task:accel-001",
        metadata={"Context budget tokens": "1500"},
    )

    result = daemon._compile_implementation_context(task, attempt=2)

    assert result.capsule.stage == "implementation"
    assert result.capsule.goal["task_id"] == "ACCEL-001"
    assert result.capsule.scope["expected_outputs"] == ("src/context.py",)
    assert result.capsule.acceptance["criteria"] == (
        "Preserve implementation authority."
    )
    resolution = result.receipt.budget_resolution
    assert resolution.reserved_output_tokens == 300
    assert resolution.reserved_tool_tokens == 100
    assert resolution.effective_input_limit == 1_500
    assert result.receipt.estimator_name == "provider_tokenizer"
    receipt_path = daemon._persist_implementation_context_receipt(
        task,
        attempt=2,
    )
    receipt_text = receipt_path.read_text(encoding="utf-8")
    receipt = json.loads(receipt_text)
    assert receipt["estimator_name"] == "provider_tokenizer"
    assert receipt["budget_resolution"]["reserved_output_tokens"] == 300
    assert "Preserve implementation authority." not in receipt_text
    assert "raw_prompt" not in receipt_text
    assert "decoded_output" not in receipt_text


@pytest.mark.parametrize("byte_limit", (12_288, 16_384))
def test_task_llm_context_budget_bounds_exact_provider_input(
    tmp_path,
    monkeypatch,
    byte_limit,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    todo_path = repo / "todo.md"
    todo_path.write_text("# Todos\n", encoding="utf-8")
    state_dir = repo / "state"
    daemon = TodoImplementationDaemon(
        todo_path=todo_path,
        state_path=state_dir / "task_state.json",
        strategy_path=state_dir / "strategy.json",
        events_path=state_dir / "events.jsonl",
        repo_root=repo,
        task_header_prefix="## VFS-",
    )
    task = PortalTask(
        task_id="VFS-900",
        title="Compile a bounded repair packet",
        status="ready",
        completion="manual",
        priority="P0",
        track="symbolic",
        outputs=["src/repair.py"],
        validation=["python -m pytest test/test_repair.py -q"],
        acceptance="Keep the invariant contract and use CID references.",
        metadata={
            "llm context budget bytes": str(byte_limit),
            "missing evidence": "contract:mismatch",
        },
        canonical_task_cid=f"task:vfs-900-{byte_limit}",
    )
    monkeypatch.setattr(
        daemon,
        "_render_todo_vector_context",
        lambda _task: "symbolic evidence " * 8_000,
    )
    monkeypatch.setattr(
        daemon,
        "_load_todo_vector_context",
        lambda _task: {},
    )

    prompt = daemon._build_implementation_prompt(task, attempt=1)
    result = daemon._last_implementation_context

    assert isinstance(result, ContextCompileResult)
    assert len(prompt.encode("utf-8")) <= byte_limit
    assert result.capsule.expansion_references
    assert all(
        item.referenced_content_id
        for item in result.capsule.expansion_references
    )
    authority = result.capsule.authority["implementation_context_budget"]
    assert authority["source"] == "task_metadata"
    assert authority["max_provider_input_bytes"] == byte_limit
    assert authority["provider_context_window"] == byte_limit + 24_576
    assert result.receipt.budget_resolution.effective_input_limit == byte_limit


