def test_run_goal_validation_preserves_quoted_validation_semicolons(tmp_path):
    repo = tmp_path / "repo"
    repo.mkdir()
    source = repo / "src" / "config.yml"
    source.parent.mkdir()
    source.write_text("enabled: true\n", encoding="utf-8")
    inline_python = (
        "python3 -c 'import pathlib, sys; "
        'p=pathlib.Path(sys.argv[1]); assert p.read_text(encoding="utf-8").strip()'
        "' src/config.yml"
    )
    goal = ObjectiveGoal(
        goal_id="VAIOS-G001",
        title="Validate config evidence",
        fields={"validation": f"{inline_python}; test -f src/config.yml"},
    )

    result = run_goal_validation(repo_root=repo, goal=goal)

    assert result["passed"] is True
    assert [item["command"] for item in result["results"]] == [inline_python, "test -f src/config.yml"]


def test_run_goal_validation_scrubs_profile_bash_env_secret_and_path_injection(
    tmp_path,
    monkeypatch,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    home = tmp_path / "home"
    home.mkdir()
    hostile_bin = tmp_path / "hostile-bin"
    hostile_bin.mkdir()
    profile_marker = tmp_path / "profile-loaded"
    bash_env_marker = tmp_path / "bash-env-loaded"
    path_marker = tmp_path / "path-shadow-ran"
    (home / ".bash_profile").write_text(
        f"touch {shlex.quote(str(profile_marker))}\n",
        encoding="utf-8",
    )
    bash_env = tmp_path / "bash-env"
    bash_env.write_text(
        f"touch {shlex.quote(str(bash_env_marker))}\n",
        encoding="utf-8",
    )
    shadow_python = hostile_bin / "python3"
    shadow_python.write_text(
        f"#!/bin/sh\ntouch {shlex.quote(str(path_marker))}\nexit 97\n",
        encoding="utf-8",
    )
    shadow_python.chmod(0o755)
    inherited_path = os.environ["PATH"]
    monkeypatch.setenv("HOME", str(home))
    monkeypatch.setenv("BASH_ENV", str(bash_env))
    monkeypatch.setenv("ENV", str(bash_env))
    monkeypatch.setenv("VALIDATION_SECRET", "must-not-leak")
    monkeypatch.setenv("PATH", f"{hostile_bin}{os.pathsep}{inherited_path}")
    monkeypatch.setenv(
        "IPFS_ACCELERATE_AGENT_VALIDATION_PATH",
        os.pathsep.join(("/usr/bin", "/bin")),
    )
    command = (
        f"test ! -e {shlex.quote(str(profile_marker))} "
        f"&& test ! -e {shlex.quote(str(bash_env_marker))} "
        '&& test -z "${VALIDATION_SECRET-}" '
        "&& python3 -c 'raise SystemExit(0)'"
    )
    goal = ObjectiveGoal(
        goal_id="VAIOS-G002",
        title="Validate isolated runtime",
        fields={"validation": command},
    )

    result = run_goal_validation(repo_root=repo, goal=goal)

    assert result["passed"] is True
    assert not profile_marker.exists()
    assert not bash_env_marker.exists()
    assert not path_marker.exists()


def test_objective_daemon_materializes_completion_proof_work_without_receipts(tmp_path):
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    _git(repo, "config", "user.name", "Test User")
    _git(repo, "config", "user.email", "test@example.invalid")
    source = repo / "src" / "proof.py"
    source.parent.mkdir()
    source.write_text("COMPLETE_RUNTIME_PROOF = True\n", encoding="utf-8")
    objective_path = repo / "objective-heap.md"
    todo_path = repo / "todo.md"
    objective_path.write_text(
        """# Objective Heap

## VAIOS-G001 Completed runtime proof

- Status: active
- Parent:
- Fib priority: 1
- Track: runtime
- Priority: P1
- Goal: Prove runtime evidence reconciliation.
- Evidence: COMPLETE_RUNTIME_PROOF
- Outputs: src/proof.py
- Validation: test -f src/proof.py
""",
        encoding="utf-8",
    )
    todo_path.write_text("# Agent Todos\n", encoding="utf-8")
    _git(repo, "add", "objective-heap.md", "todo.md", "src/proof.py")
    _git(repo, "commit", "-m", "seed completed objective")
    args = build_arg_parser().parse_args(
        [
            "--repo-root",
            str(repo),
            "--objective-path",
            str(objective_path),
            "--todo-path",
            str(todo_path),
            "--task-prefix",
            "ACCEL-",
            "--max-findings",
            "1",
            "--no-persist-ast-dataset",
        ]
    )

    payload = run_objective_daemon(args)

    assert payload["completed_goal_ids"] == []
    assert payload["objective_active_goal_count"] == 1
    assert payload["objective_completed_goal_count"] == 0
    assert payload["objective_completion_validation_results"] == {}
    assert payload["objective_completion_decisions"]["VAIOS-G001"]["state"] == "provisionally_complete"
    assert payload["objective_generated_work_count"] == 1
    assert payload["objective_generation_materialized_count"] == 1
    assert payload["generated_count"] == 1
    objective_text = objective_path.read_text(encoding="utf-8")
    assert "- Status: provisionally_complete" in objective_text
    assert "- Completion evidence:" not in objective_text
    todo_text = todo_path.read_text(encoding="utf-8")
    assert (
        "## ACCEL-001 Review completion-evidence alignment for "
        "Completed runtime proof"
    ) in todo_text
    assert "- Goal id: VAIOS-G001" in todo_text
    assert "- Predicted files:\n" in todo_text
    assert "- Validation: git diff --check; test -f src/proof.py" in todo_text
    generated_work = payload["objective_generation"]["generated_work"]
    assert len(generated_work) == 1
    assert generated_work[0]["source"] == "completion_gate_gap_manual_review"
    assert generated_work[0]["family_key"]
    assert generated_work[0]["instance_key"]

    replay = run_objective_daemon(args)

    assert replay["objective_generation_materialized_count"] == 0
    assert todo_path.read_text(encoding="utf-8").count("## ACCEL-001 ") == 1


