def test_objective_daemon_refines_missing_evidence_into_child_goals(tmp_path):
    repo, objective_path, todo_path = _seed_repo(tmp_path)
    args = build_arg_parser().parse_args(
        [
            "--repo-root",
            str(repo),
            "--objective-path",
            str(objective_path),
            "--todo-path",
            str(todo_path),
            "--refine-objective-heap",
            "--max-refinement-children",
            "1",
            "--task-prefix",
            "ACCEL-",
            "--max-findings",
            "2",
            "--no-persist-ast-dataset",
        ]
    )

    payload = run_objective_daemon(args)
    goals = parse_goal_heap(objective_path.read_text(encoding="utf-8"))
    refined = [goal for goal in goals if goal.goal_id in payload["refined_goal_ids"]]

    assert payload["refined_goal_ids"] == ["VAIOS-G011"]
    assert payload["generated_count"] == 1
    assert len(refined) == 1
    assert refined[0].parent_goal_ids == ["VAIOS-G010"]
    assert refined[0].required_evidence == ["missing_gesture_policy"]
    assert refined[0].fields["fib_priority"] == str(fibonacci_priority(1, 0))
    todo_text = todo_path.read_text(encoding="utf-8")
    assert "Prove missing_gesture_policy for Meta display control bridge" in todo_text


def test_bundle_member_completion_receipts_use_terminal_canonical_evidence(tmp_path):
    state_dir = tmp_path / "objective-runtime" / "state"
    state_dir.mkdir(parents=True)
    event_path = state_dir / "agent_objective_runtime_events.jsonl"
    rotated_path = state_dir / "agent_objective_runtime_events.jsonl.rotated-20260722T120000Z"
    rotated_path.write_text(
        json.dumps(
            {
                "type": "todo_status_updated",
                "timestamp": "2026-07-22T12:00:00+00:00",
                "task_id": "ACCEL-001",
                "canonical_task_cid": "cid-completed-from-status",
                "canonical_task_key": "task/v1/status",
                "updated": True,
                "updated_task_ids": ["ACCEL-001"],
            }
        )
        + "\n",
        encoding="utf-8",
    )
    event_path.write_text(
        "\n".join(
            [
                json.dumps(
                    {
                        "type": "implementation_finished",
                        "timestamp": "2026-07-22T12:01:00+00:00",
                        "task_id": "ACCEL-002",
                        "canonical_task_cid": "cid-completed-from-merge",
                        "returncode": 0,
                        "merge_result": {"merged": True},
                    }
                ),
                json.dumps(
                    {
                        "type": "implementation_finished",
                        "timestamp": "2026-07-22T12:02:00+00:00",
                        "task_id": "ACCEL-003",
                        "canonical_task_cid": "cid-failed",
                        "returncode": 1,
                        "merge_result": {"merged": False},
                    }
                ),
                json.dumps(
                    {
                        "type": "task_completed",
                        "timestamp": "2026-07-22T12:03:00+00:00",
                        "task_id": "ACCEL-004",
                        "canonical_task_cid": "cid-non-authoritative",
                    }
                ),
                json.dumps(
                    {
                        "type": "todo_status_updated",
                        "timestamp": "2026-07-22T12:04:00+00:00",
                        "task_id": "ACCEL-005",
                        "updated": True,
                        "updated_task_ids": ["ACCEL-005"],
                        "completion_receipts": [
                            {"task_id": "ACCEL-005", "status": "succeeded"}
                        ],
                    }
                ),
            ]
        )
        + "\n",
        encoding="utf-8",
    )

    receipts = bundle_member_completion_receipts(tmp_path)

    assert set(receipts) == {"cid-completed-from-status", "cid-completed-from-merge"}
    assert receipts["cid-completed-from-status"]["event_path"] == str(rotated_path)
    assert receipts["cid-completed-from-merge"]["task_id"] == "ACCEL-002"


def test_goal_packet_aggregate_releases_every_covered_member_dependency(
    monkeypatch,
    tmp_path,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    todo_path = repo / "aggregate.todo.md"
    todo_path.write_text(
        """# Aggregate packet

## T-COVERED-A Covered packet member A

- Status: todo
- Completion: manual
- Priority: P1
- Track: runtime
- Bundle: objective/aggregate
- Goal packet: goal_packet/runtime/shared
- Goal packet role: packet_member
- Candidate kind: aggregate

## T-COVERED-B Covered packet member B

- Status: todo
- Completion: manual
- Priority: P1
- Track: runtime
- Bundle: objective/aggregate
- Goal packet: goal_packet/runtime/shared
- Goal packet role: packet_member
- Candidate kind: aggregate

## T-AGGREGATE Complete the shared goal packet

- Status: todo
- Completion: manual
- Priority: P1
- Track: runtime
- Bundle: objective/aggregate
- Merge family: goal_packet/runtime/shared
- Merge role: packet_aggregate
- Goal packet: goal_packet/runtime/shared
- Goal packet role: packet_aggregate
- Candidate kind: goal_packet_aggregate
""",
        encoding="utf-8",
    )
    indexed_tasks = {
        task.task_id: task
        for task in parse_task_file(todo_path, task_header_prefix="## T-")
    }
    vector_index = repo / "objective_bundles" / "todo_vector_index.json"
    vector_index.parent.mkdir(parents=True)
    vector_index.write_text(
        json.dumps(
            {
                "records": [
                    {
                        "task_id": task_id,
                        "canonical_task_cid": f"cid-{task_id.casefold()}",
                        "canonical_task_key": f"task/v1/{task_id.casefold()}",
                        "title": task_id,
                        "canonical_task_key": indexed_tasks[task_id].canonical_task_key,
                        "canonical_task_cid": indexed_tasks[task_id].canonical_task_cid,
                        "task_cid": indexed_tasks[task_id].canonical_task_cid,
                        "bundle_key": "objective/aggregate",
                        "candidate_kind": candidate_kind,
                        "merge_family": "goal_packet/runtime/shared",
                        "merge_role": merge_role,
                        "goal_packet_key": "goal_packet/runtime/shared",
                        "goal_packet_role": packet_role,
                    }
                    for task_id, candidate_kind, merge_role, packet_role in (
                        ("T-COVERED-A", "aggregate", "aggregate", "packet_member"),
                        ("T-COVERED-B", "aggregate", "aggregate", "packet_member"),
                        (
                            "T-AGGREGATE",
                            "goal_packet_aggregate",
                            "packet_aggregate",
                            "packet_aggregate",
                        ),
                    )
                ],
                "execution_packets": [
                    {
                        "packet_key": "execution_packet/runtime/shared",
                        "primary_task_id": "T-AGGREGATE",
                        "primary_task_cid": indexed_tasks[
                            "T-AGGREGATE"
                        ].canonical_task_cid,
                        "active_task_ids": [
                            "T-AGGREGATE",
                            "T-COVERED-A",
                            "T-COVERED-B",
                        ],
                        "completion_binding": {
                            "primary_task_id": "T-AGGREGATE",
                            "primary_task_cid": indexed_tasks[
                                "T-AGGREGATE"
                            ].canonical_task_cid,
                            "bound_sibling_task_ids": [
                                "T-COVERED-A",
                                "T-COVERED-B",
                            ],
                            "bound_sibling_task_cids": [
                                indexed_tasks[
                                    "T-COVERED-A"
                                ].canonical_task_cid,
                                indexed_tasks[
                                    "T-COVERED-B"
                                ].canonical_task_cid,
                            ],
                            "packet_key": "goal_packet/runtime/shared",
                            "canonical_task_keys": {
                                indexed_tasks[
                                    "T-AGGREGATE"
                                ].canonical_task_cid: indexed_tasks[
                                    "T-AGGREGATE"
                                ].canonical_task_key,
                                indexed_tasks[
                                    "T-COVERED-A"
                                ].canonical_task_cid: indexed_tasks[
                                    "T-COVERED-A"
                                ].canonical_task_key,
                                indexed_tasks[
                                    "T-COVERED-B"
                                ].canonical_task_cid: indexed_tasks[
                                    "T-COVERED-B"
                                ].canonical_task_key,
                            },
                            "binding_id": hashlib.sha1(
                                json.dumps(
                                    {
                                        "primary_task_cid": indexed_tasks[
                                            "T-AGGREGATE"
                                        ].canonical_task_cid,
                                        "bound_sibling_task_cids": [
                                            indexed_tasks[
                                                "T-COVERED-A"
                                            ].canonical_task_cid,
                                            indexed_tasks[
                                                "T-COVERED-B"
                                            ].canonical_task_cid,
                                        ],
                                        "packet_key": "goal_packet/runtime/shared",
                                        "canonical_task_keys": {
                                            indexed_tasks[
                                                "T-AGGREGATE"
                                            ].canonical_task_cid: indexed_tasks[
                                                "T-AGGREGATE"
                                            ].canonical_task_key,
                                            indexed_tasks[
                                                "T-COVERED-A"
                                            ].canonical_task_cid: indexed_tasks[
                                                "T-COVERED-A"
                                            ].canonical_task_key,
                                            indexed_tasks[
                                                "T-COVERED-B"
                                            ].canonical_task_cid: indexed_tasks[
                                                "T-COVERED-B"
                                            ].canonical_task_key,
                                        },
                                    },
                                    sort_keys=True,
                                ).encode("utf-8")
                            ).hexdigest(),
                        },
                    }
                ],
            }
        ),
        encoding="utf-8",
    )
    state_root = repo / "state"
    lane_state = state_root / "objective-aggregate" / "state"
    lane_state.mkdir(parents=True)
    strategy_path = lane_state / "strategy.json"
    strategy_path.write_text(
        json.dumps(
            {
                "last_objective_todo_vector_index_path": (
                    "objective_bundles/todo_vector_index.json"
                )
            }
        ),
        encoding="utf-8",
    )
    daemon = TodoImplementationDaemon(
        todo_path=todo_path,
        state_path=lane_state / "agent_objective_aggregate_task_state.json",
        strategy_path=strategy_path,
        events_path=lane_state / "agent_objective_aggregate_events.jsonl",
        repo_root=repo,
        task_header_prefix="## T-",
    )
    tasks = parse_task_file(todo_path, task_header_prefix="## T-")
    daemon._register_task_identities(tasks)
    aggregate = next(task for task in tasks if task.task_id == "T-AGGREGATE")
    expected_identities = {
        task_id: daemon._task_identity_by_display_id[task_id]
        for task_id in ("T-AGGREGATE", "T-COVERED-A", "T-COVERED-B")
    }

    completion = daemon._mark_task_or_bundle_completed_in_todo(aggregate)
    receipts = bundle_member_completion_receipts(state_root)

    assert completion["updated_task_ids"] == [
        "T-AGGREGATE",
        "T-COVERED-A",
        "T-COVERED-B",
    ]
    completion_receipts = {
        receipt["task_id"]: receipt
        for receipt in completion["completion_receipts"]
    }
    assert set(completion_receipts) == set(expected_identities)
    assert {
        task_id: receipt["canonical_task_cid"]
        for task_id, receipt in completion_receipts.items()
    } == {
        task_id: identity.canonical_task_cid
        for task_id, identity in expected_identities.items()
    }
    assert all(
        receipt["status"] == "succeeded"
        and receipt["schema"].endswith("member_completion_receipt@1")
        for receipt in completion_receipts.values()
    )
    persisted_event = json.loads(
        (lane_state / "agent_objective_aggregate_events.jsonl")
        .read_text(encoding="utf-8")
        .splitlines()[-1]
    )
    assert persisted_event["completion_receipts"] == completion["completion_receipts"]
    assert set(receipts) == {
        identity.canonical_task_cid for identity in expected_identities.values()
    }
    assert {
        receipt["task_id"] for receipt in receipts.values()
    } == set(expected_identities)
    assert all(receipt["status"] == "succeeded" for receipt in receipts.values())

    bundle_index = repo / "bundle-index.json"
    (repo / "downstream.todo.md").write_text(
        """# Downstream packet

## T-DOWNSTREAM Downstream task

- Status: todo
- Completion: manual
""",
        encoding="utf-8",
    )
    bundle_index.write_text(
        json.dumps(
            {
                "source_todo": str(todo_path),
                "bundles": {
                    "objective/aggregate": {
                        "shard_path": str(todo_path),
                        "tasks": [
                            {
                                "task_id": task_id,
                                "canonical_task_cid": identity.canonical_task_cid,
                                "canonical_task_key": identity.canonical_task_key,
                            }
                            for task_id, identity in expected_identities.items()
                        ],
                    },
                    "objective/downstream": {
                        "shard_path": "downstream.todo.md",
                        "tasks": [
                            {
                                "task_id": "T-DOWNSTREAM",
                                "canonical_task_cid": "cid-downstream",
                                "depends_on": [
                                    "T-COVERED-A",
                                    "T-COVERED-B",
                                ],
                            }
                        ],
                    },
                },
            }
        ),
        encoding="utf-8",
    )
    lanes = plan_bundle_lanes(
        bundle_index_path=bundle_index,
        repo_root=repo,
        state_root=state_root,
        worktree_root=repo / "worktrees",
        log_dir=repo / "logs",
        task_prefix="## T-",
    )
    by_key = {lane.bundle_key: lane for lane in lanes}

    assert by_key["objective/aggregate"].task_ids == []
    downstream = by_key["objective/downstream"]
    assert downstream.claimable is True
    assert downstream.task_ids == ["T-DOWNSTREAM"]
    assert downstream.dependency_task_cids == []

    starts = []

    class Process:
        pid = 4321

    def fake_popen(command, **_kwargs):
        starts.append(list(command))
        return Process()

    monkeypatch.setattr(
        "ipfs_accelerate_py.agent_supervisor.objectives.bundle_supervisor.subprocess.Popen",
        fake_popen,
    )
    launched = launch_bundle_lanes(
        [downstream],
        repo_root=repo,
        coordination_path=repo / "coordination.sqlite3",
    )

    assert launched[0]["accepted"] is True
    assert len(starts) == 1


