def test_implementation_supervisor_refreshes_merge_state_after_checkout_lease(
    tmp_path,
    monkeypatch,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    state_dir = repo / "state"
    supervisor = TodoImplementationSupervisor(
        TodoSupervisorConfig(
            todo_path=repo / "todo.md",
            state_path=state_dir / "task_state.json",
            strategy_path=state_dir / "strategy.json",
            events_path=state_dir / "events.jsonl",
            state_dir=state_dir,
            repo_root=repo,
        )
    )
    merge_heads = iter(
        [
            {"ok": False, "merge_head": "", "error": "transient query"},
            {"ok": True, "merge_head": ""},
        ]
    )
    unmerged_paths = iter(
        [
            {"ok": True, "unmerged_paths": []},
            {"ok": True, "unmerged_paths": []},
        ]
    )
    monkeypatch.setattr(
        supervisor,
        "_git_merge_head_query",
        lambda _repo: next(merge_heads),
    )
    monkeypatch.setattr(
        supervisor,
        "_git_unmerged_paths_query",
        lambda _repo: next(unmerged_paths),
    )
    monkeypatch.setattr(
        supervisor,
        "_repair_main_checkout_merge_state_locked",
        lambda *_args, **_kwargs: pytest.fail(
            "clean state refreshed under the lease must not be repaired"
        ),
    )

    result = supervisor.repair_main_checkout_merge_state()

    assert result == {
        "attempted": False,
        "repaired": False,
        "reason": "clean",
        "path": str(repo),
    }
    assert not supervisor._repo_merge_lock_path().exists()


def test_implementation_supervisor_defers_when_locked_merge_query_fails(
    tmp_path,
    monkeypatch,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    state_dir = repo / "state"
    supervisor = TodoImplementationSupervisor(
        TodoSupervisorConfig(
            todo_path=repo / "todo.md",
            state_path=state_dir / "task_state.json",
            strategy_path=state_dir / "strategy.json",
            events_path=state_dir / "events.jsonl",
            state_dir=state_dir,
            repo_root=repo,
        )
    )
    merge_heads = iter(
        [
            {"ok": True, "merge_head": "observed-before-lock"},
            {
                "ok": False,
                "merge_head": "",
                "error": "locked query failed",
            },
        ]
    )
    unmerged_paths = iter(
        [
            {"ok": True, "unmerged_paths": ["conflict.txt"]},
            {"ok": True, "unmerged_paths": []},
        ]
    )
    monkeypatch.setattr(
        supervisor,
        "_git_merge_head_query",
        lambda _repo: next(merge_heads),
    )
    monkeypatch.setattr(
        supervisor,
        "_git_unmerged_paths_query",
        lambda _repo: next(unmerged_paths),
    )
    monkeypatch.setattr(
        supervisor,
        "_repair_main_checkout_merge_state_locked",
        lambda *_args, **_kwargs: pytest.fail(
            "unknown locked state must not be repaired or treated as clean"
        ),
    )

    result = supervisor.repair_main_checkout_merge_state()

    assert result["attempted"] is True
    assert result["repaired"] is False
    assert result["reason"] == "main_checkout_merge_state_refresh_failed"
    assert result["merge_head_query"]["ok"] is False
    assert not supervisor._repo_merge_lock_path().exists()


def test_implementation_supervisor_aborts_interrupted_main_checkout_merge_with_reset_fallback(
    tmp_path,
    monkeypatch,
):
    repo = tmp_path / "repo"
    repo.mkdir()
    _git(repo, "init")
    _git(repo, "checkout", "-b", "main")
    _git(repo, "config", "user.name", "Test User")
    _git(repo, "config", "user.email", "test@example.invalid")
    target = repo / "conflict.txt"
    target.write_text("base\n", encoding="utf-8")
    _git(repo, "add", "conflict.txt")
    _git(repo, "commit", "-m", "base")
    _git(repo, "checkout", "-b", "implementation/conflict")
    target.write_text("feature\n", encoding="utf-8")
    _git(repo, "commit", "-am", "feature")
    _git(repo, "checkout", "main")
    target.write_text("main\n", encoding="utf-8")
    _git(repo, "commit", "-am", "main")
    merge = subprocess.run(["git", "merge", "implementation/conflict"], cwd=repo, text=True, capture_output=True)
    assert merge.returncode != 0

    from ipfs_accelerate_py.agent_supervisor.todo_daemon import (
        implementation_supervisor as implementation_supervisor_module,
    )

    real_run = implementation_supervisor_module.subprocess.run

    def fail_merge_abort(command, *args, **kwargs):
        if list(command) == ["git", "merge", "--abort"]:
            return subprocess.CompletedProcess(command, 1, "", "simulated abort failure")
        return real_run(command, *args, **kwargs)

    monkeypatch.setattr(implementation_supervisor_module.subprocess, "run", fail_merge_abort)
    supervisor = TodoImplementationSupervisor(
        TodoSupervisorConfig(
            todo_path=repo / "todo.md",
            state_path=repo / "state" / "task_state.json",
            strategy_path=repo / "state" / "strategy.json",
            events_path=repo / "state" / "events.jsonl",
            state_dir=repo / "state",
            repo_root=repo,
        )
    )

    result = supervisor.repair_main_checkout_merge_state()

    assert result["repaired"] is True
    assert result["abort_result"]["aborted"] is True
    assert result["abort_result"]["returncode"] == 1
    assert result["abort_result"]["reset_merge_fallback"]["reset"] is True
    assert supervisor._git_merge_head(repo) == ""
    assert supervisor._git_unmerged_paths(repo) == []
    assert target.read_text(encoding="utf-8") == "main\n"


