    (
        _tasks_by_id,
        _task_ids_by_branch,
        outcome_keys,
        _provenance_by_branch,
    ) = supervisor._reconciliation_task_context(
        ReconciliationContextDaemon()
    )

    assert semantic_failure_key in outcome_keys
    assert missing_executable_key not in outcome_keys


